let passed=0,failed=0;function assert(a,e){a?(passed+=1,console.log(`  ✓ ${e}`)):(failed+=1,console.error(`  ✗ ${e}`))}function section(a,e){console.log(`\n${a}`),e()}async function runTests(){const{AWARD_ENCYCLOPEDIA:a,filterAwardsByCategory:e}=await(import("../frontend/js-modules/national-awards.js"));section("National Awards Encyclopedia Integrity Check",()=>{const e=Object.values(a);assert(e.length>=10,`AWARD_ENCYCLOPEDIA has ${e.length} awards (expected >= 10)`),assert(void 0!==a["bharat-ratna"],"Bharat Ratna exists"),assert(void 0!==a["param-vir-chakra"],"Param Vir Chakra exists"),assert(void 0!==a["khel-ratna"],"Khel Ratna exists"),assert(void 0!==a["jnanpith-award"],"Jnanpith exists")}),section("Category Filtering Test",()=>{const a=e("civilian");assert(a.length>=4,`civilian category has ${a.length} awards (expected >= 4)`);const s=e("gallantry");assert(s.length>=6,`gallantry category has ${s.length} awards (expected >= 6)`)}),console.log(`\nTest Summary: ${passed} passed, ${failed} failed.`),failed>0&&process.exit(1)}runTests();